+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import org.springframework.beans.factory.annotation.Autowired;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private TextField nameField;
+    private EmailField emailField;
+    private TextField phoneField;
+    private TextArea messageField;
+    private Button sendButton;
+    private Grid<Message> grid;
+    private MessageService messageService;
+    private boolean sendDisabledAfterSend = false;
+
+    @Autowired
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = createForm();
+        add(form);
+
+        grid = new Grid<>(Message.class, false);
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getText).setHeader("Message");
+        grid.setItems(messageService.getMessages());
+        add(grid);
+    }
+
+    private FormLayout createForm() {
+        FormLayout form = new FormLayout();
+
+        nameField = new TextField("Name");
+        nameField.setWidthFull();
+
+        emailField = new EmailField("Email");
+        emailField.setWidthFull();
+
+        phoneField = new TextField("Phone");
+        phoneField.setWidthFull();
+
+        messageField = new TextArea("Message");
+        messageField.setWidthFull();
+
+        sendButton = new Button("Send");
+
+        // Add listeners for enabling Send button when user edits
+        nameField.addValueChangeListener(event -> {
+            sendDisabledAfterSend = false;
+            sendButton.setEnabled(true);
+        });
+        emailField.addValueChangeListener(event -> {
+            sendDisabledAfterSend = false;
+            sendButton.setEnabled(true);
+        });
+        phoneField.addValueChangeListener(event -> {
+            sendDisabledAfterSend = false;
+            sendButton.setEnabled(true);
+        });
+        messageField.addValueChangeListener(event -> {
+            sendDisabledAfterSend = false;
+            sendButton.setEnabled(true);
+        });
+
+        sendButton.addClickListener(event -> handleSend());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        form.add(nameField, emailField, phoneField, messageField);
+        form.add(sendButton);
+
+        return form;
+    }
+
+    private void handleSend() {
+        // Clear previous error states
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+
+        boolean isValid = true;
+
+        // Validate name
+        if (nameField.getValue().trim().isEmpty()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            isValid = false;
+        }
+
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+
+        // Validate email if provided
+        if (!email.isEmpty() && !isValidEmail(email)) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+
+        // Validate that either email or phone is provided
+        if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+
+        // Validate message
+        String message = messageField.getValue();
+        if (message.trim().isEmpty()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            isValid = false;
+        } else if (message.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (isValid) {
+            // Save the message
+            Message msg = new Message(
+                nameField.getValue(),
+                email.isEmpty() ? "" : email,
+                phone.isEmpty() ? "" : phone,
+                message
+            );
+            messageService.addMessage(msg);
+
+            // Update grid
+            grid.setItems(messageService.getMessages());
+
+            // Show notification
+            Notification notification = new Notification("Message sent");
+            notification.open();
+
+            // Clear form
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+
+            // Disable send button
+            sendButton.setEnabled(false);
+            sendDisabledAfterSend = true;
+        }
+    }
+
+    private boolean isValidEmail(String email) {
+        return email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        // Check if any field has content
+        boolean hasContent = !nameField.getValue().trim().isEmpty() ||
+                            !emailField.getValue().trim().isEmpty() ||
+                            !phoneField.getValue().trim().isEmpty() ||
+                            !messageField.getValue().trim().isEmpty();
+
+        if (hasContent) {
+            event.postpone();
+
+            Dialog confirmDialog = new Dialog();
+            confirmDialog.setHeaderTitle("Discard changes?");
+
+            Button keepButton = new Button("Keep editing", e -> confirmDialog.close());
+            Button discardButton = new Button("Discard", e -> {
+                confirmDialog.close();
+                event.forwardTo(event.getNavigationTarget());
+            });
+
+            confirmDialog.getFooter().add(keepButton, discardButton);
+            confirmDialog.open();
+        }
+    }
+}
